function hideOverlays(){const o=$<HTMLDivElement>('#overlay');if(o)o.innerHTML='';}
function showMenu(){clearRaceSession();const o=$<HTMLDivElement>('#overlay');o.innerHTML=`<div class="overlay"><div class="card"><div class="eyebrow">MANUAL TRACKED ROBOT RACING</div><h1>ROBO RACE<br><span style="color:#eab449">3D</span></h1><p>Drive the prototype through an indoor competition course. Pass every numbered gate in sequence, cross each obstacle, then reach the finish. This is direct manual control—there is no line following.</p><div><span class="tag">11 ORDERED SECTIONS</span><span class="tag">DIFFERENTIAL TRACK DRIVE</span><span class="tag">FULL ARENA ROUTE</span></div><p style="font-size:11px;margin:13px 0 15px"><b>Keyboard:</b> W/S forward and reverse · A/D steer · Space brake · R recover · C camera · Esc pause<br><b>Touch:</b> stick vertical drives each track; stick horizontal steers.</p><button class="action" id="start">START RACE</button><div class="subactions"><button class="iconbtn" id="menuCam">CAMERA: CHASE</button><button class="iconbtn" id="menuSettings">DRIVING SETTINGS</button></div></div></div>`;$('#start',o).addEventListener('click',startRace);$('#menuCam',o).addEventListener('click',cycleCamera);$('#menuSettings',o).addEventListener('click',()=>$('#settings').classList.toggle('hidden'));}
